from pptx import Presentation
from pptx.enum.shapes import MSO_SHAPE_TYPE
from lxml import etree

prs = Presentation('/root/Awesome-Agent-Papers_processed.pptx')
print(f'Total slides: {len(prs.slides)}')
print(f'Slide size: {prs.slide_width}x{prs.slide_height}')

for i, slide in enumerate(prs.slides):
    print(f'\n=== Slide {i+1} ===')
    for j, shape in enumerate(slide.shapes):
        if shape.shape_type == MSO_SHAPE_TYPE.TEXT_BOX:
            print(f'  TEXT_BOX \"{shape.name}\": \"{shape.text[:100]}\"')
            print(f'    left={shape.left}, top={shape.top}, w={shape.width}, h={shape.height}')
            # Check if bottom center
            expected_left = (prs.slide_width - shape.width) // 2
            print(f'    Centered: left_expected={expected_left}, actual={shape.left}, match={expected_left == shape.left}')
            print(f'    Bottom: top + height = {shape.top + shape.height}, slide_height = {prs.slide_height}')
            # Check formatting via XML
            xml = etree.tostring(shape._element, pretty_print=True).decode()
            if 'b=\"0\"' in xml or 'b=\"1\"' in xml:
                print(f'    Bold attribute found: b=0 (good)' if 'b=\"0\"' in xml else '    Bold: b=1 (BAD)')
            if '989596' in xml:
                print(f'    Color #989596: found (good)')
            if 'Arial' in xml:
                print(f'    Font Arial: found (good)')
            if 'sz=\"1600\"' in xml:
                print(f'    Font size 16pt (1600): found (good)')

    # Check Reference slide
    if i == len(prs.slides) - 1:
        print('  --- Reference slide content ---')
        for j, shape in enumerate(slide.shapes):
            print(f'  Shape {j}: type={shape.shape_type}, name=\"{shape.name}\"')
            if hasattr(shape, 'text'):
                print(f'    Text: \"{shape.text[:200]}\"')
            if shape.has_text_frame:
                for k, para in enumerate(shape.text_frame.paragraphs):
                    print(f'    Para {k}: \"{para.text[:120]}\"')
                    # Check for auto-numbering
                    pPr = para._p.find('{http://schemas.openxmlformats.org/drawingml/2006/main}pPr')
                    if pPr is not None:
                        buAuto = pPr.find('{http://schemas.openxmlformats.org/drawingml/2006/main}buAutoNum')
                        if buAuto is not None:
                            print(f'      Auto-number type: {buAuto.get(\"type\")}')
